import{_ as i}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a,a as t,b as r,c as o,d as s}from"./chunks/M-STA5.Cj8YAhfJ.js";import{_ as l,o as n,c,a3 as m}from"./chunks/framework.g9mfNVRQ.js";const S=JSON.parse('{"title":"Statistiche","description":"","frontmatter":{"source_hash":"cf4c58239c","source_commit":"7a18e7c"},"headers":[],"relativePath":"it/use/statistics.md","filePath":"it/use/statistics.md"}'),d={name:"it/use/statistics.md"};function p(u,e,g,_,h,b){return n(),c("div",null,[...e[0]||(e[0]=[m('<div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_chart_areaspline_grey600_48dp.png" style="width:5%;"> Statistiche</p></div><p>La schermata Statistiche offre 3 visualizzazioni statistiche di base che puoi configurare per diversi periodi di tempo.</p><ol><li>Per prima cosa seleziona il periodo su cui calcolare le statistiche: oggi, ieri, ultimi 7, 30 o 90 giorni.</li><li>Puoi visualizzare il grafico a schermo intero (toccalo di nuovo per uscire dalla modalità a schermo intero).</li><li>Puoi condividere la schermata come screenshot.</li></ol><img src="'+a+'" style="zoom:75%;"><br><p>La prima schermata mostra i tuoi numeri.</p><img src="'+t+'" style="zoom:75%;"><p>La percentuale nel range è calcolata usando i valori basso e alto definiti in Menu - Unità di Misura Glicemia.<br> I numeri assoluti contano le misure nel range, sopra e sotto.<br> La glicemia mediana è il valore centrale dei tuoi dati: lo stesso numero di misure sta sopra e sotto.<br> La glicemia media è la media aritmetica di tutte le misure.<br> L&#39;HbA1c stimata è solo un calcolo matematico basato sulla glicemia media, convertito in mmol/mol o in percentuale.<br> La StdDev, o deviazione standard, è il risultato di un calcolo matematico. Mostra la dispersione della tua glicemia.<br> La SD relativa (CV) è la StdDev divisa per la media e mostra anch&#39;essa la dispersione delle tue misure.<br> GVI e PGS sono parametri introdotti da Dexcom, vedi <a href="https://web.archive.org/web/20160523152519/http://www.healthline.com/diabetesmine/a-new-view-of-glycemic-variability-how-long-is-your-line" target="_blank" rel="noreferrer">qui</a>.</p><p>Guarda <a href="https://diatribe.org/understanding-average-glucose-standard-deviation-cv-and-blood-sugar-variability" target="_blank" rel="noreferrer">qui</a> per la spiegazione di questi parametri, e ricorda che si basano sulle misure e dipendono dalla loro qualità. Misure sbagliate (imprecise) daranno statistiche sbagliate, che dipenda dalla precisione del sensore o dalle tue calibrazioni.</p><p>Puoi scegliere quali di questi valori mostrare. Tocca il menu (⋮) in alto a destra e seleziona <code>Parameters</code>, poi spunta o togli la spunta a: Numeri assoluti, Glicemia Mediana, HbA1c stimata, STD relativa, GVI, PGS, Deviazione Standard.</p><br><p>Scorri verso sinistra per vedere una rappresentazione grafica della percentuale nel range.<br> Il verde è nel range, il giallo sopra e il rosso sotto l&#39;obiettivo.</p><img src="'+r+'" style="zoom:75%;"><br><p>Scorri di nuovo per vedere il grafico dei percentili.</p><img src="'+o+'" style="zoom:75%;"><p>Ruota lo schermo per una visualizzazione migliore.</p><img src="'+s+'" style="zoom:50%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.03" target="_blank" rel="noreferrer"><em>Ultima modifica 6/7/2026</em></a></p>',20)])])}const y=l(d,[["render",p]]);export{S as __pageData,y as default};
